    @classmethod
    def get_dosing_guideline(cls, rxcui: str, gfr: float) -> str:
        data = cls.FORMULATIONS.get(rxcui)
        if not data: return "Standard dosing"
        if gfr < 30.0 and data["renal_elimination_pct"] > 50.0:
            return "Reduce daily dose by 50% due to severe renal impairment."
        elif gfr < 60.0 and data["renal_elimination_pct"] > 50.0:
            return "Reduce daily dose by 25% due to moderate renal impairment."
        return "Standard therapeutic dose recommended."
